internal class GUPPriceEngineDatasourceAggregationObject
{
    // Table name or attribute privider name.
    // Refer to GUPIPricingAttribute.getQueryBuilderDatasourceIdentifier();
    private str datasourceId;
    
    // Can be any leaf class of GUPIPricingAttribute. Here we only need to use its super method.
    private GUPIPricingAttribute datasourceAttribute;
    
    // RecId of all lines (from TA, margin component, etc) that contain the datasource.
    private Set lineRecIdSet;

    // All data fields (in string) that includes in any journal. 
    private Set dataFieldIdSet;

    private GUPPricingAttributeSourceLevel sourceLevel;


}

Method.Source:
    public void new (str _datasourceId, GUPIPricingAttribute _pricingAttribute)
    {
        super();
        this.datasourceId = _datasourceId;
        this.datasourceAttribute = _pricingAttribute;
        this.dataFieldIdSet = new Set(Types::String);
        this.lineRecIdSet = new Set(Types::Int64);

        this.sourceLevel = this.checkSourceLevel(_pricingAttribute);
    }

    private GUPPricingAttributeSourceLevel checkSourceLevel(GUPIPricingAttribute _pricingAttribute)
    {
        if(classIdGet(_pricingAttribute) == classNum(GUPPricingAttributeEcoResAttribute))
        {
            GUPPricingAttributeEcoResAttribute ecoResAttribute = _pricingAttribute;
            return ecoResAttribute.getSourceLevel();
        }
        else 
        {
            DictClass dc = new DictClass(classIdGet(_pricingAttribute));
            GUPPricingAttributeSourceDiscoveryAttribute sourceAttribute = dc.getAttribute('GUPPricingAttributeSourceDiscoveryAttribute');
            return sourceAttribute.parmLevel();
        }

    }
